SELECT o.id, o.symbol, o.execution_source, o.started_at, s.generated_at, TIMESTAMPDIFF(MICROSECOND, o.started_at, s.generated_at) / 1000000 AS age_s, m.entry_quality_score, p.id AS paper_id, p.status, p.realized_pnl FROM execution_opportunity o JOIN trade_signal s ON s.id = o.latest_signal_id LEFT JOIN wallet_managed_position m ON m.entry_signal_id = s.id LEFT JOIN paper_position p ON p.signal_id = s.id WHERE o.status = 'EXECUTED' AND o.executed_at >= '2026-10-01 00:00:00' AND (TIMESTAMPDIFF(SECOND, o.started_at, s.generated_at) BETWEEN 1197 AND 1263 OR TIMESTAMPDIFF(SECOND, o.started_at, s.generated_at) BETWEEN 2397 AND 2463 OR TIMESTAMPDIFF(SECOND, o.started_at, s.generated_at) BETWEEN 3597 AND 3663) ORDER BY o.executed_at LIMIT 60